const TIME_TOL := 0.5 / 60.0
const VAL_TOL := 1e-4
const SEAM_TOL := 1e-3
const REST_Y := -20.14

const KEY_TIMES := [0.0, 2.0 / 60.0, 4.0 / 60.0, 8.0 / 60.0]
