	check("UpperSprite Sprite2D under UpperPivot", upper_sprite != null and upper_sprite.get_class() == "Sprite2D", str(upper_sprite))
	var scripted: Array[String] = []
	var stack: Array[Node] = [visuals]
	while not stack.is_empty():
		var n: Node = stack.pop_back()
		if n.get_script() != null:
			scripted.append(str(visuals.get_path_to(n)))
		stack.append_array(n.get_children())
	check("no scripts on any node", scripted.is_empty(), str(scripted))
	if lower_pivot == null or upper_pivot == null or lower_sprite == null or upper_sprite == null:
		finish()
		return

	check("LowerPivot rest position (0, 0)", lower_pivot.position == Vector2.ZERO, v2s(lower_pivot.position))
	check("LowerPivot rest scale (1, 1)", lower_pivot.scale == Vector2.ONE, v2s(lower_pivot.scale))
	check("UpperPivot rest position (0, -20.14)", near2(upper_pivot.position, Vector2(0, REST_Y), VAL_TOL), v2s(upper_pivot.position))
	check("UpperPivot rest scale (1, 1)", upper_pivot.scale == Vector2.ONE, v2s(upper_pivot.scale))

	for entry in [["LowerSprite", lower_sprite, Rect2(0, 622, 1024, 402), Vector2(-512, -190)],
			["UpperSprite", upper_sprite, Rect2(0, 0, 1024, 622), Vector2(-512, -622)]]:
		var nm: String = entry[0]
		var s: Sprite2D = entry[1]
		var tex_path := s.texture.resource_path if s.texture != null else "<null>"
		check("%s texture path" % nm, tex_path == IDLE_PATH, tex_path)
		check("%s region_enabled true" % nm, s.region_enabled == true, str(s.region_enabled))
		check("%s region_rect %s" % [nm, entry[2]], s.region_rect == entry[2], str(s.region_rect))
		check("%s offset %s" % [nm, entry[3]], s.offset == entry[3], str(s.offset))
		check("%s centered false" % nm, s.centered == false, str(s.centered))
		check("%s position (0, 0)" % nm, s.position == Vector2.ZERO, v2s(s.position))
		check("%s scale (0.106, 0.106)" % nm, s.scale.is_equal_approx(Vector2(0.106, 0.106)), v2s(s.scale))
		check("%s texture_filter LINEAR_WITH_MIPMAPS" % nm, s.texture_filter == CanvasItem.TEXTURE_FILTER_LINEAR_WITH_MIPMAPS, "%d (constant %d)" % [s.texture_filter, CanvasItem.TEXTURE_FILTER_LINEAR_WITH_MIPMAPS])

	# --- AnimationPlayer and library
	var player := visuals.get_node_or_null("AnimationPlayer") as AnimationPlayer
	check("AnimationPlayer present", player != null, str(player))
	if player == null:
		finish()
		return
	var libs := player.get_animation_library_list()
	check("exactly one library, the default \"\"", libs.size() == 1 and libs[0] == &"", str(libs))
	check("no RESET animation", not player.has_animation(&"RESET"), str(player.get_animation_list()))
	check("clip scoot exists", player.has_animation(&"scoot"), str(player.get_animation_list()))
	check("clip land exists", player.has_animation(&"land"), str(player.get_animation_list()))
	var problems := track_problems(player)
	for p in problems:
		print("  track problem: " + p)
	check("every track of every clip resolves (track_problems)", problems.is_empty(), "%d problems over clips %s" % [problems.size(), player.get_animation_list()])
	if not player.has_animation(&"land"):
		finish()
		return
	var clip := player.get_animation(&"land")
	check("land resource path", clip.resource_path == LAND_PATH, clip.resource_path)

	# --- Clip settings
	check("length 8/60", near(clip.length, 8.0 / 60.0, TIME_TOL), "%.10f vs %.10f" % [clip.length, 8.0 / 60.0])
	check("step 1/60", is_equal_approx(clip.step, 1.0 / 60.0), "%.10f vs %.10f" % [clip.step, 1.0 / 60.0])
	check("loop_mode LOOP_NONE", clip.loop_mode == Animation.LOOP_NONE, "%d (constant %d)" % [clip.loop_mode, Animation.LOOP_NONE])

	# --- Tracks
	var n_tracks := clip.get_track_count()
	check("land has exactly three tracks", n_tracks == 3, str(n_tracks))
	var paths: Array[String] = []
	for t in n_tracks:
		paths.append(str(clip.track_get_path(t)))
	var expected_paths: Array[String] = [P_LOWER_SCALE, P_UPPER_POS, P_UPPER_SCALE]
	var sorted_paths := paths.duplicate()
	sorted_paths.sort()
	var sorted_expected := expected_paths.duplicate()
	sorted_expected.sort()
	check("track paths are exactly the three rig paths", sorted_paths == sorted_expected, str(paths))
	check("no track on %s" % P_FORBIDDEN, not (P_FORBIDDEN in paths), str(paths))

	var idx := {}
	for t in n_tracks:
		var path: String = paths[t]
		idx[path] = t
		var is_value := clip.track_get_type(t) == Animation.TYPE_VALUE
		check("track %d (%s) type TYPE_VALUE" % [t, path], is_value, "%d (constant %d)" % [clip.track_get_type(t), Animation.TYPE_VALUE])
		if is_value:
			var mode := clip.value_track_get_update_mode(t)
			check("track %d (%s) update mode CONTINUOUS" % [t, path], mode == Animation.UPDATE_CONTINUOUS, "%d (constant %d)" % [mode, Animation.UPDATE_CONTINUOUS])
		else:
			check("track %d (%s) update mode CONTINUOUS" % [t, path], false, "not a value track; update mode not read")
		var interp := clip.track_get_interpolation_type(t)
		check("track %d (%s) interpolation LINEAR" % [t, path], interp == Animation.INTERPOLATION_LINEAR, "%d (constant %d)" % [interp, Animation.INTERPOLATION_LINEAR])

	# --- Keys
	var keys_ok := true
	for path in expected_paths:
		if not idx.has(path):
			check("%s present for key checks" % path, false, "missing")
			keys_ok = false
			continue
		var t: int = idx[path]
		var n_keys := clip.track_get_key_count(t)
		check("%s has four keys" % path, n_keys == 4, str(n_keys))
		if n_keys != 4:
			keys_ok = false
			continue
		for k in 4:
			var kt := clip.track_get_key_time(t, k)
			check("%s key %d time %.6f" % [path, k, KEY_TIMES[k]], near(kt, KEY_TIMES[k], TIME_TOL), "%.10f (diff %.10f)" % [kt, kt - KEY_TIMES[k]])
			var kv = clip.track_get_key_value(t, k)
			var vok: bool = typeof(kv) == TYPE_VECTOR2 and near2(kv, KEY_VALUES[path][k], VAL_TOL)
			check("%s key %d value %s" % [path, k, KEY_VALUES[path][k]], vok, "%s (type %s)" % [v2s(kv) if typeof(kv) == TYPE_VECTOR2 else str(kv), type_string(typeof(kv))])
			if typeof(kv) != TYPE_VECTOR2:
				keys_ok = false
			var tr := clip.track_get_key_transition(t, k)
			check("%s key %d transition %.1f" % [path, k, KEY_TRANSITIONS[k]], near(tr, KEY_TRANSITIONS[k], VAL_TOL), "%.6f" % tr)

	if keys_ok:
		var tl: int = idx[P_LOWER_SCALE]
		var tp: int = idx[P_UPPER_POS]
		var tu: int = idx[P_UPPER_SCALE]
		for k in 4:
			var ls: Vector2 = clip.track_get_key_value(tl, k)
			var up: Vector2 = clip.track_get_key_value(tp, k)
			var us: Vector2 = clip.track_get_key_value(tu, k)
			check("key %d equal widths (LowerPivot.scale.x == UpperPivot.scale.x)" % k, near(ls.x, us.x, VAL_TOL), "%.6f vs %.6f" % [ls.x, us.x])
			check("key %d UpperPivot.position.x == 0" % k, near(up.x, 0.0, VAL_TOL), "%.6f" % up.x)
			var seam := REST_Y * ls.y
			check("key %d seam UpperPivot.position.y == -20.14 * LowerPivot.scale.y" % k, near(up.y, seam, SEAM_TOL), "%.6f vs %.6f (diff %.8f)" % [up.y, seam, up.y - seam])
		# Frame-8 key equals the scene's rest values.
		var ls8: Vector2 = clip.track_get_key_value(tl, 3)
		var up8: Vector2 = clip.track_get_key_value(tp, 3)
		var us8: Vector2 = clip.track_get_key_value(tu, 3)
		check("frame-8 LowerPivot:scale equals scene rest", near2(ls8, lower_pivot.scale, VAL_TOL), "%s vs %s" % [v2s(ls8), v2s(lower_pivot.scale)])
		check("frame-8 UpperPivot:position equals scene rest", near2(up8, upper_pivot.position, VAL_TOL), "%s vs %s" % [v2s(up8), v2s(upper_pivot.position)])
		check("frame-8 UpperPivot:scale equals scene rest", near2(us8, upper_pivot.scale, VAL_TOL), "%s vs %s" % [v2s(us8), v2s(upper_pivot.scale)])

		# --- Between keys (Animation.value_track_interpolate)
		if not has_interpolate:
			check("between-key samples via value_track_interpolate", false, "method missing on this build; not worked around")
		else:
			for frame: int in [1, 3, 5, 6, 7]:
				var time: float = frame / 60.0
				var s_ls: Vector2 = clip.call("value_track_interpolate", tl, time)
				var s_up: Vector2 = clip.call("value_track_interpolate", tp, time)
				var s_us: Vector2 = clip.call("value_track_interpolate", tu, time)
				print("SAMPLE frame %d t=%.6f LowerPivot:scale %s UpperPivot:position %s UpperPivot:scale %s" % [frame, time, v2s(s_ls), v2s(s_up), v2s(s_us)])
				var seam := REST_Y * s_ls.y
				check("frame %d seam UpperPivot.position.y == -20.14 * LowerPivot.scale.y" % frame, near(s_up.y, seam, SEAM_TOL), "%.6f vs %.6f (diff %.8f)" % [s_up.y, seam, s_up.y - seam])
				check("frame %d equal widths" % frame, near(s_ls.x, s_us.x, SEAM_TOL), "%.6f vs %.6f" % [s_ls.x, s_us.x])
				if frame == 6:
					check("frame 6 width 1.0375", near(s_ls.x, 1.0375, SEAM_TOL), "%.6f" % s_ls.x)
					check("frame 6 LowerPivot scale.y 0.90", near(s_ls.y, 0.90, SEAM_TOL), "%.6f" % s_ls.y)
					check("frame 6 UpperPivot scale.y 0.9325", near(s_us.y, 0.9325, SEAM_TOL), "%.6f" % s_us.y)
					check("frame 6 UpperPivot position.y -18.126", near(s_up.y, -18.126, SEAM_TOL), "%.6f (display %.2f)" % [s_up.y, s_up.y])

	finish()

func finish() -> void:
	print("A7 LAND READBACK: %d checks / %d failures" % [checks, failures])
	quit(1 if failures else 0)

	## Snap the camera to x; smoothing (the glide back on respawn) applies to later moves.
	camera.position = Vector2(x, T.VIEW.y / 2.0)
	camera.reset_smoothing()
	camera.position_smoothing_enabled = smooth

func _start_intro() -> void:
	## Panel 1: eye-level pan from the dome back to the jelly. Movement is locked.
	state = State.INTRO
	intro_ticks = 0
	player.enabled = false
	music.restart()
	_set_camera(T.level_width() - T.VIEW.x / 2.0, false)

func start_session() -> void:
	## Begin play on the first plate: when the intro pan ends or is skipped, or on replay after
	## the dome (no pan). Every fork cycle and the checkpoint reset.
	if state == State.PLAYING:
		return
	if state == State.WON:
		music.restart()   # replay: the loop starts again from the top
	splats = 0
	checkpoint = 0
	jelly_plate = 0
	prompt_shown = false
	won_once = false
	shake_ticks = 0
	camera.offset = Vector2.ZERO
	for fork in forks:
		if fork:
			fork.reset_cycle()
	_begin_play(spawn_point(0))
	_set_camera(camera_target_x(), true)

func _begin_play(at: Vector2) -> void:
	state = State.PLAYING
	timer = 0.0
	# Area2D overlaps are physics-step snapshots. Discard pre-teleport contacts
	# until the broadphase has observed the reset, preventing a phantom second splat.
	contact_settle_ticks = 2
	player.reset_at(at)
	player.enabled = true
	# Control returns: the checkpoint fork's safe window begins now (panel 6, failure #12).
	if forks[checkpoint]:
		forks[checkpoint].restart_at_safe()

func set_paused(value: bool) -> void:
	if value and state == State.PLAYING:
		state = State.PAUSED
		player.enabled = false
	elif not value and state == State.PAUSED:
		state = State.PLAYING
		player.enabled = true
		player.require_fresh_press()

func _on_focus_lost() -> void:
	if not test_mode:
		set_paused(true)

func resolve_contacts(cause: String, finished: bool) -> void:
	## cause: "" (none), "fork" or "sauce". A failure wins over reaching the goal.
	if state != State.PLAYING:
		return
	if cause != "":
		state = State.SPLAT
		splats += 1
		splat_cause = cause
		timer = T.SPLAT_TIME
		player.enabled = false
		player.velocity = Vector2.ZERO
		# One splat sound per failure: hits stay off until control returns.
		sound.play("SFX-SPLAT-FORK" if cause == "fork" else "SFX-SPLAT-SAUCE")
		if cause == "fork":
			shake_ticks = T.ticks(T.SHAKE_TIME)   # camera only; never on a sauce splat
		# The jelly will re-form on the checkpoint plate: hold that fork raised until control returns.
		if forks[checkpoint]:
			forks[checkpoint].hold_raised()
	elif finished:
		state = State.WON
		timer = 0.0
		prompt_shown = false
		win_from = player.position
		player.enabled = false
		player.velocity = Vector2.ZERO
		if not won_once:
			won_once = true
			sound.play("SFX-WIN")

func view_rect() -> Rect2:
	return Rect2(camera.get_screen_center_position() - T.VIEW / 2.0, T.VIEW)

func shadow_on_screen(fork) -> bool:
	return view_rect().intersects(fork.shadow_rect())

func _advance_forks() -> void:
	## Forks keep their fixed rhythm during play, splat and re-form (paused, intro and win freeze them).
	for fork in forks:
		if fork and fork.advance() == "down":
			# SFX-WARN (Kiran, 2026-10-03, after the second audition): the scrape plays once when the fork
			# over the jelly's current or next plate starts descending, if that fork is on screen at that
			# moment. Nothing plays when a shadow starts growing; the shadow alone does the warning.
			fork.announced = shadow_on_screen(fork) and fork.plate_index in [jelly_plate, jelly_plate + 1]
			if fork.announced:
				on_warning(fork)

func on_warning(_fork) -> void:
	sound.play("SFX-WARN")   # once per strike, as the fork starts descending

func warnings_on_screen() -> int:
	## Forks warning (shadow growing, or striking) with any part of the shadow on screen.
	## CHANGE-BRIEF.md music rule (Kiran, 2026-10-03): a shadow that started off screen dips
	## the music once it is on screen, though it never plays SFX-WARN.
	var n := 0
	for fork in forks:
		if fork and fork.is_warning() and shadow_on_screen(fork):
			n += 1
	return n

func music_target() -> String:
	match state:
		State.INTRO:
			return "intro"
		State.PAUSED:
			return "pause"
		State.WON:
			return "end_quiet" if prompt_shown else "win_fade"
		State.SPLAT, State.REFORM:
			return "splat"
	return "warning" if warnings_on_screen() > 0 else "normal"

func _physics_process(delta: float) -> void:
	if state in [State.PLAYING, State.SPLAT, State.REFORM]:
		_advance_forks()
	match state:
		State.INTRO:
			intro_ticks += 1
			var k := clampf(float(intro_ticks) / float(T.ticks(T.INTRO_PAN)), 0.0, 1.0)
			var from := T.level_width() - T.VIEW.x / 2.0
			camera.position.x = lerpf(from, camera_target_x(), ease(k, -2.0))   # ease in-out
			if k >= 1.0:
				start_session()
		State.WON:
			# Slide into the dome, then wait for the prompt (panel 7).
			timer += delta
			var k := clampf(timer / T.WIN_SLIDE, 0.0, 1.0)
			var dome_center := Vector2(T.dome_left() + T.dome_width() / 2.0, T.TABLE_TOP)
			player.position = win_from.lerp(dome_center, 1.0 - (1.0 - k) * (1.0 - k))
			if timer >= T.PROMPT_DELAY:
				prompt_shown = true
		State.SPLAT:
			timer -= delta
			if timer <= 0.0:
				# Re-form on the last safe plate; hits stay off and input stays locked.
				state = State.REFORM
				timer = T.REFORM_TIME
				player.reset_at(spawn_point(checkpoint))
				jelly_plate = checkpoint
		State.REFORM:
			timer -= delta
			if timer <= 0.0:
				_begin_play(spawn_point(checkpoint))
		State.PLAYING:
			timer += delta
			var cause := ""
			for sauce in sauce_areas:
				if sauce.overlaps_body(player):
					cause = "sauce"
			for fork in forks:
				if fork and fork.hit_area.overlaps_body(player):
					cause = "fork"
			if contact_settle_ticks > 0:
				contact_settle_ticks -= 1
			else:
				resolve_contacts(cause, goal.overlaps_body(player))
			if state == State.PLAYING and player.just_landed:
				# Airborne -> grounded, and not into sauce (that is a splat). Respawn is not a landing.
				sound.play("SFX-LAND")
				var p := plate_under(player.position.x)
				if p >= 0:
					checkpoint = p
	if state != State.INTRO:
		camera.position.x = camera_target_x()   # smoothing gives the glide back on respawn
	if shake_ticks > 0:
		shake_ticks -= 1
		var amount := T.SHAKE_PX * float(shake_ticks) / float(T.ticks(T.SHAKE_TIME))
		camera.offset = Vector2(shake_rng.randf_range(-1, 1), shake_rng.randf_range(-1, 1)) * amount
	else:
		camera.offset = Vector2.ZERO
	music.set_target(music_target())
	var under := plate_under(player.position.x)
	if under >= 0 and player.is_on_floor() and state == State.PLAYING:
		jelly_plate = under
	player.worried = state == State.PLAYING and under >= 0 and forks[under] != null and forks[under].phase() == Fork.Phase.SHADOW
	player.override_pose = {State.SPLAT: "SPLAT", State.REFORM: "RESPAWN", State.WON: "CELEBRATE"}.get(state, "")
	if is_instance_valid(hud):
		hud.queue_redraw()

func _unhandled_input(event: InputEvent) -> void:
	if not (event is InputEventKey) or event.echo or not event.pressed:
		return
	# M and N only toggle mute; muting never changes game state, so they never skip or restart.

var created := 0
var freed := 0

func _initialize() -> void:
	call_deferred("run")

func run() -> void:
	game = load("res://game/main.tscn").instantiate()
	game.test_mode = true
	root.add_child(game)
	var driver: Node = null
	for child in game.get_children():
		if child.get_script() == DRIVER:
			driver = child
	var glints: GPUParticles2D = driver.glints
	game.remove_child(driver)
	driver.free()
	glints.free()
	for pressed in [true, false]:
		var ev := InputEventKey.new()
		ev.keycode = KEY_ENTER
		ev.physical_keycode = KEY_ENTER
		ev.pressed = pressed
		Input.parse_input_event(ev)
		await process_frame
	print("PEAK state after Enter: ", game.state)
	start = Engine.get_physics_frames()
	last_tick = start - 1
	var hist_all := {}
	var hist_live := {}
	var peak_all := 0
	var peak_live := 0
	for i in range(WARMUP + FRAMES):
		await process_frame
		var now := Engine.get_physics_frames()
		for k in range(last_tick + 1, now + 1):
			var t := (k - start) % LIFE
			if t == 0 or t == GAP:
				pending += 1
		last_tick = now
		while pending > 0 and live < MAX_LIVE:
			spawn()
			pending -= 1
		if i == WARMUP:
			counting = true
		if counting:
			var n_all := 0
			var n_live := 0
			for child in game.get_children():
				if child.scene_file_path == PUFF_PATH:
					n_all += 1
					if not child.is_queued_for_deletion():
						n_live += 1
			hist_all[n_all] = hist_all.get(n_all, 0) + 1
			hist_live[n_live] = hist_live.get(n_live, 0) + 1
			peak_all = maxi(peak_all, n_all)
			peak_live = maxi(peak_live, n_live)
	print("PEAK counted frames: ", FRAMES, " after ", WARMUP, " warm-up frames")
	print("PEAK puffs in the tree (including queued for deletion): ", peak_all, " | frames per count: ", hist_all)
	print("PEAK puffs not queued for deletion: ", peak_live, " | frames per count: ", hist_live)
